fn main(){let a:Vec<_>=std::env::args().collect();if a.len()!=5{std::process::exit(2)}let r=std::panic::catch_unwind(||{let receipt=full(Path::new(&a[1]),Path::new(&a[2]),Path::new(&a[3]));fs::OpenOptions::new().write(true).create_new(true).open(&a[4]).unwrap().write_all((serde_json::to_string(&receipt).unwrap()+"\n").as_bytes()).unwrap();});if r.is_err(){std::process::exit(101)}}
